package com.autocare.service;import com.autocare.dto.response.*;import com.autocare.enums.*;import com.autocare.repository.*;import com.autocare.security.*;import jakarta.transaction.Transactional;import org.springframework.security.access.AccessDeniedException;import org.springframework.stereotype.Service;import java.time.*;import java.util.*;
@Service @Transactional public class DashboardService{private final AppointmentRepository appointments;private final ServiceCaseRepository cases;private final VehicleRepository vehicles;private final NotificationService notifications;private final CurrentUserService current;public DashboardService(AppointmentRepository a,ServiceCaseRepository c,CustomerRepository cu,VehicleRepository v,NotificationService n,CurrentUserService x){appointments=a;cases=c;vehicles=v;notifications=n;current=x;}public WorkshopDashboardResponse workshop(){if(!Set.of("EMPLOYEE","MANAGER","OWNER").contains(current.requireCurrentUser().role()))throw new AccessDeniedException("Workshop access is required");var all=cases.findAll();return new WorkshopDashboardResponse(appointments.findAll().stream().filter(a->a.getRequestedDate().equals(LocalDate.now())).count(),all.stream().filter(c->c.getVisitType()==VisitType.WALK_IN&&c.getCheckInTime()!=null&&c.getCheckInTime().atZone(ZoneId.systemDefault()).toLocalDate().equals(LocalDate.now())).count(),all.stream().filter(c->c.getStatus()==ServiceCaseStatus.IN_SERVICE).count(),all.stream().filter(c->c.getStatus()==ServiceCaseStatus.WAITING_FOR_APPROVAL).count(),all.stream().filter(c->c.getStatus()==ServiceCaseStatus.READY_FOR_PICKUP).count(),all.stream().filter(c->c.getPriority()==Priority.HIGH||c.getPriority()==Priority.CRITICAL).count(),all.stream().filter(c->c.getStatus()==ServiceCaseStatus.COMPLETED).count());}public CustomerDashboardResponse customer(){var c=current.requireCurrentCustomer();return new CustomerDashboardResponse(vehicles.findByCustomer_CustomerId(c.getCustomerId()).size(),cases.findAll().stream().filter(x->x.getCustomer().getId().equals(c.getId())&&!Set.of(ServiceCaseStatus.COMPLETED,ServiceCaseStatus.CANCELLED).contains(x.getStatus())).count(),notifications.unread());}}
